// Общие шаги для тестов «возврат к объявлению после входа из попапа связи» (#083d10).
// Прод, гость: не входить, SMS-код не запрашивать, окно Google не открывать, формы не отправлять.
import { expect, Page } from '@playwright/test';

export const LISTING_ID = '4d62fda8-629a-4ad5-9913-3f925cbbb1d1';
export const LISTING_URL = `/businessdetail?id=${LISTING_ID}`;
/** Загрузка объявления/выдачи на проде под параллельной нагрузкой бывает 10+ с. */
export const LOAD = { timeout: 20_000 };
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

/**
 * Подготовка гостевой страницы (вызывать до первого перехода):
 * - все не-GET/HEAD/OPTIONS запросы отклоняются;
 * - запросы к Google OAuth / supabase authorize обрываются;
 * - баннер cookie заранее закрыт выбором «только необходимые» (как «חיוניים בלבד»).
 */
export async function prepareGuest(page: Page) {
  await page.route('**/*', (route) => {
    const req = route.request();
    if (/accounts\.google\.com|\/auth\/v1\/authorize/.test(req.url())) return route.abort('blockedbyclient');
    return SAFE_METHODS.includes(req.method()) ? route.fallback() : route.abort('blockedbyclient');
  });
  await page.addInitScript(() => {
    try {
      if (!localStorage.getItem('cookie-consent-v2')) {
        localStorage.setItem(
          'cookie-consent-v2',
          JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
        );
      }
    } catch {}
  });
}

/** Попап «הרשמה קלה, מהירה וחד-פעמית». */
export const loginPopup = (page: Page) => page.getByRole('dialog').filter({ hasText: 'הרשמה' });

export const readRedirectAfterLogin = (page: Page) =>
  page.evaluate(() => sessionStorage.getItem('redirectAfterLogin'));

/** Дождаться конца анимации появления попапа. */
export async function waitPopupSettled(page: Page) {
  const dlg = loginPopup(page);
  await expect(dlg).toBeVisible(LOAD);
  await dlg.evaluate((d) => Promise.all(d.getAnimations({ subtree: true }).map((a) => a.finished)));
}

// ---- #a88c1c: отказ от входа очищает адрес возврата и намерение ----

/** Текст намерения на /auth при заходе из попапа связи (#6ce2cc). */
export const INTENT_BIZ = 'להתעניין בעסקים';
/** Текст намерения на /auth при заходе из «פרסם עסק» (#6ce2cc). */
export const INTENT_PUBLISH = 'לפרסם באתר';
/** Общий заголовок обычного /auth (#6ce2cc). */
export const PLAIN_AUTH_TITLE = 'ברוכים הבאים';

/** Адрес возврата указывает на это объявление с contact=1. */
export async function expectReturnToListing(page: Page, step: string) {
  const saved = await readRedirectAfterLogin(page);
  expect(saved, `${step}: redirectAfterLogin записан`).not.toBeNull();
  const target = new URL(saved!, 'https://x');
  expect(target.pathname, `${step}: возврат — на объявление`).toBe('/businessdetail');
  expect(target.searchParams.get('id'), `${step}: то же объявление`).toBe(LISTING_ID);
  expect(target.searchParams.get('contact'), `${step}: contact=1`).toBe('1');
}

/** redirectAfterLogin отсутствует (очистка может идти сразу после перехода — ждём результат). */
export async function expectNoReturn(page: Page, step: string) {
  await expect.poll(() => readRedirectAfterLogin(page), { message: `${step}: redirectAfterLogin отсутствует`, ...LOAD }).toBeNull();
}

/**
 * Гость: объявление → «הצג מספר טלפון» → попап → «כניסה / הרשמה עם SMS» → /auth?mode=sms.
 * Исходное состояние сценариев #a88c1c: адрес возврата записан, текст намерения показан.
 * На /auth ничего не нажимается.
 */
export async function openAuthFromPopup(page: Page) {
  await page.goto(LISTING_URL);
  await page.getByRole('button', { name: 'הצג מספר טלפון' }).first().click({ timeout: LOAD.timeout });
  const popup = loginPopup(page);
  await expect(popup, 'открылся попап входа').toBeVisible(LOAD);
  await popup.getByRole('button', { name: /SMS/ }).click();
  await page.waitForURL((u) => u.pathname === '/auth' && u.searchParams.get('mode') === 'sms', LOAD);
  await expect(page.getByText('שלח קוד').first(), 'экран SMS на /auth').toBeVisible(LOAD);
  await expect(page.getByText(INTENT_BIZ).first(), 'на /auth из попапа — текст намерения').toBeVisible();
  await expectReturnToListing(page, '/auth из попапа');
}

/** Обычный экран входа: общий заголовок, без текстов намерения, без адреса возврата. */
export async function expectPlainAuth(page: Page, step: string) {
  expect(new URL(page.url()).pathname, `${step}: адрес /auth`).toBe('/auth');
  await expect(page.getByText(PLAIN_AUTH_TITLE).first(), `${step}: общий заголовок «${PLAIN_AUTH_TITLE}»`).toBeVisible(LOAD);
  await expect(page.getByText('התחברו לחשבון שלכם').first(), `${step}: «התחברו לחשבון שלכם»`).toBeVisible();
  await expect(page.getByText(INTENT_BIZ), `${step}: нет «${INTENT_BIZ}»`).toHaveCount(0);
  await expect(page.getByText(INTENT_PUBLISH), `${step}: нет «${INTENT_PUBLISH}»`).toHaveCount(0);
  await expectNoReturn(page, step);
}
